<?php require __DIR__.'/../config/app.php';header('Content-Type: application/json');$s=strtoupper(trim($_GET['symbol']??''));$stock=q('SELECT * FROM stocks WHERE symbol=?',[$s])->fetch();$prices=q('SELECT ts,open,high,low,close,volume FROM prices WHERE symbol=? ORDER BY ts DESC LIMIT 500',[$s])->fetchAll();echo json_encode(['stock'=>$stock,'prices'=>array_reverse($prices)]);